  var MEMO_LOGO = 'data:image/png;base64,';
  var memoData = [];
  var memoBtns = [];   // [{name,kitchen,price,net}]  price=ราคาปกติ (gross) · net=ราคาหลังลด
  var memoLinked = null;  // ชื่อแคมเปญในระบบที่ memo นี้ผูกอยู่ (สำหรับยืนยันส่ง/เช็คสถานะ)
  var MEMO_BLOCKS = [
    { id:'header',    label:'หัวเอกสาร', on:true, note:'' },
    { id:'supersede', label:'หมายเหตุยกเลิก', on:false, note:'' },
    { id:'footer',    label:'ข้อมูลเอกสาร (หัวข้อ/แผนก/วันที่/ถึง)', on:true, note:'' },
    { id:'title',     label:'ชื่อแคมเปญ', on:true, note:'' },
    { id:'keys',      label:'ข้อมูลหลัก', on:true, note:'' },
    { id:'detail',    label:'รายละเอียด', on:true, note:'' },
    { id:'condition', label:'เงื่อนไข', on:true, note:'' },
    { id:'special',   label:'เงื่อนไขพิเศษ (แดง)', on:true, note:'' },
    { id:'buttons',   label:'ปุ่มกด POS', on:true, note:'' },
  ];

  var TH_MONTH = ['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  function memoEsc(s){ return String(s==null?'':s).replace(/[&<>"]/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c];}); }
  function parseISO(s){ var m=String(s||'').match(/(\d{4})-(\d{2})-(\d{2})/); if(!m) return null; return { y:+m[1], mo:+m[2], d:+m[3] }; }
  function thDate(s){ var p=parseISO(s); if(!p) return String(s||''); return p.d+' '+TH_MONTH[p.mo-1]+' '+(p.y+543); }
  function thRange(a,b){ var pa=parseISO(a), pb=parseISO(b); if(!pa&&!pb) return ''; if(!pa) return thDate(b); if(!pb) return thDate(a);
    if(pa.y===pb.y){ if(pa.mo===pb.mo) return pa.d+' – '+pb.d+' '+TH_MONTH[pb.mo-1]+' '+(pb.y+543); return pa.d+' '+TH_MONTH[pa.mo-1]+' – '+pb.d+' '+TH_MONTH[pb.mo-1]+' '+(pb.y+543); }
    return thDate(a)+' – '+thDate(b); }
  function ddmmyyyy(d){ var p=(d instanceof Date)? {d:d.getDate(),mo:d.getMonth()+1,y:d.getFullYear()} : parseISO(d); if(!p) return '-'; return String(p.d).padStart(2,'0')+'/'+String(p.mo).padStart(2,'0')+'/'+p.y; }

  window.initMemo = function () {
    google.script.run.withSuccessHandler(function (sum) {
      const m = document.getElementById('memoMonth');
      if (m) m.innerHTML = '<option value="ALL">ทุกเดือน</option>' + (sum || []).map(s => `<option value="${s.month}">Promotion ${s.month}</option>`).join('');
    }).getMonthlySubmitSummary();
    memoBtns = [{name:'',kitchen:'',price:'',net:''}];
    window.memoRenderBlocks();
    window.memoRenderBtnRows();
    window.memoLoadCampaigns();
    window.memoBuild();
    window.memoRenderStatus();
  };

  window.memoLoadCampaigns = function (cb) {
    const month = document.getElementById('memoMonth') ? document.getElementById('memoMonth').value : 'ALL';
    google.script.run.withSuccessHandler(function (data) {
      memoData = (data || []).filter(c => c.opStatus === 'CONFIRMED' && (c.changeStatus || '') !== 'CANCELLED' && (month === 'ALL' || c.month === month));
      const sel = document.getElementById('memoPull');
      sel.innerHTML = '<option value="">' + (memoData.length ? '— เลือกเพื่อเติมข้อมูล —' : 'ยังไม่มีแคมเปญที่ตรวจสอบแล้ว') + '</option>'
        + memoData.map((c,i)=>`<option value="${i}">${memoEsc(c.campaign)}</option>`).join('');
      window.memoRenderStatus();
      if (typeof cb === 'function') cb();
    }).getMemoCampaigns('ALL');
  };

  // ค้นหาชื่อโปร — กรองรายการใน dropdown ตามคำที่พิมพ์ (คง value = index เดิมใน memoData)
  window.memoFilterCampaigns = function () {
    var q = ((document.getElementById('memoPullSearch') || {}).value || '').trim().toLowerCase();
    var sel = document.getElementById('memoPull'); if (!sel) return;
    var list = memoData.map(function (c, i) { return { c: c, i: i }; });
    if (q) list = list.filter(function (o) { return String(o.c.campaign || '').toLowerCase().indexOf(q) > -1; });
    sel.innerHTML = '<option value="">' + (list.length ? '— เลือกเพื่อเติมข้อมูล —' : 'ไม่พบชื่อโปรที่ค้นหา') + '</option>'
      + list.map(function (o) { return '<option value="' + o.i + '">' + memoEsc(o.c.campaign) + '</option>'; }).join('');
  };

  window.memoFillFromCampaign = function () {
    const sel = document.getElementById('memoPull');
    const idx = sel.value;
    if (idx === '') { Swal.fire({icon:'info', title:'ยังไม่ได้เลือกแคมเปญ', text:'เลือกแคมเปญจากรายการ หรือพิมพ์ข้อมูลเองด้านล่าง', confirmButtonColor:'#2e934a'}); return; }
    const c = memoData[+idx]; if (!c) return;
    memoLinked = c.campaign;
    const set = (id,v)=>{ const e=document.getElementById(id); if(e) e.value=v; };
    set('memoSubject', c.campaign || '');
    set('memoPeriod', thRange(c.start, c.end));
    set('memoChannels', c.saleMode || '');
    const stores = (c.storeData || []);
    set('memoBranches', stores.length ? (stores.length + ' สาขาที่ร่วมรายการ') : 'ทุกสาขาที่ร่วมรายการ');
    set('memoBtnType', c.promoType || '');
    // รายละเอียดโปรโมชั่น: ดึงรายละเอียด "ทุกปุ่ม" มาเรียงเป็นข้อ (ไม่เบียดในตาราง)
    var detailLines = (c.buttons||[])
      .map(b=>String(b.detail||'').replace(/\r/g,'').replace(/\n+/g,' ').trim())
      .filter(Boolean);
    // fallback ถ้าปุ่มไม่มี detail → ใช้ detail ระดับแคมเปญ
    if (!detailLines.length && c.detail) detailLines = String(c.detail).replace(/\r/g,'').split('\n').map(s=>s.trim()).filter(Boolean);
    // ตัดเลขนำหน้าเดิมออก + ตัดซ้ำ (คงลำดับ)
    var seen={}; detailLines = detailLines.map(s=>s.replace(/^\s*\d+[\.\)]\s*/,'').trim()).filter(s=>{ if(seen[s])return false; seen[s]=1; return true; });
    set('memoDetail', detailLines.join('\n'));
    // เงื่อนไข: ดึง mechanic/condition ทุกปุ่ม (ตัด note ภายใน [STAGE]/[TEST]) → ต่อท้ายส่วนรายละเอียด
    var condLines = (c.buttons||[])
      .map(b=>String(b.condition||b.mechanic||'').replace(/\r/g,'').replace(/\n+/g,' ').trim())
      .filter(Boolean);
    if (!condLines.length && (c.mechanic||c.condition)) condLines = String(c.mechanic||c.condition).replace(/\r/g,'').split('\n').map(s=>s.trim()).filter(Boolean);
    var seenC={}; condLines = condLines
      .filter(s=>!/^\[(stage|test)\]/i.test(s))
      .map(s=>s.replace(/^\s*\d+[\.\)]\s*/,'').trim())
      .filter(s=>{ if(!s||seenC[s])return false; seenC[s]=1; return true; });
    set('memoCondition', condLines.join('\n'));
    // เงื่อนไขพิเศษ (ป้ายแดง branchNote ที่ IT ตั้ง) → ดึงมาโชว์ใน Memo เป็นแถบสีแดง
    var specLines = (c.buttons||[]).map(b=>String(b.branchNote||'').replace(/\r/g,'').replace(/\n+/g,' ').trim()).filter(Boolean);
    if (!specLines.length && c.branchNote) specLines = String(c.branchNote).replace(/\r/g,'').split('\n').map(s=>s.trim()).filter(Boolean);
    var seenS={}; specLines = specLines.map(s=>s.replace(/^\s*\d+[\.\)]\s*/,'').trim()).filter(s=>{ if(!s||seenS[s])return false; seenS[s]=1; return true; });
    set('memoSpecial', specLines.join('\n'));
    if (c.start) set('memoEff', parseISO(c.start) ? c.start.slice(0,10) : '');
    memoBtns = (c.buttons||[]).length
      ? c.buttons.map(b=>({ name:b.shortName||'', kitchen:b.kitchen||'', price:(b.gross!==undefined&&b.gross!=='')?String(b.gross):'', net:(b.net!==undefined&&b.net!=='')?String(b.net):'' }))
      : [{name:'',kitchen:'',price:'',net:''}];
    // turn on the detail/buttons blocks since we now have data
    MEMO_BLOCKS.forEach(b=>{ if(b.id==='detail'||b.id==='condition'||b.id==='special'||b.id==='buttons'||b.id==='keys') b.on=true; });
    window.memoRenderBlocks();
    window.memoRenderBtnRows();
    window.memoBuild();
    window.memoRenderStatus();
    Swal.fire({icon:'success', title:'ดึงข้อมูลแล้ว', text:'แก้ไขเพิ่มเติมได้ทุกช่อง', timer:1300, showConfirmButton:false});
  };

  /* ---- POS button rows editor ---- */
  window.memoRenderBtnRows = function () {
    const box = document.getElementById('memoBtnRows');
    box.innerHTML = memoBtns.map((b,i)=>`
      <div class="mb-row">
        <input class="form-control form-control-sm border-dark" value="${memoEsc(b.name)}" placeholder="ชื่อปุ่ม" oninput="window.memoBtnEdit(${i},'name',this.value)">
        <input class="form-control form-control-sm border-dark" value="${memoEsc(b.kitchen)}" placeholder="ครัว/บิล" oninput="window.memoBtnEdit(${i},'kitchen',this.value)">
        <input class="form-control form-control-sm border-dark" value="${memoEsc(b.price)}" placeholder="ราคาปกติ" oninput="window.memoBtnEdit(${i},'price',this.value)">
        <input class="form-control form-control-sm border-dark" value="${memoEsc(b.net)}" placeholder="ราคาหลังลด" oninput="window.memoBtnEdit(${i},'net',this.value)">
        <button class="mb-x" title="ลบ" onclick="window.memoDelBtn(${i})">×</button>
      </div>`).join('');
  };
  window.memoBtnEdit = function (i, k, v) { if(memoBtns[i]){ memoBtns[i][k]=v; window.memoBuild(); } };
  window.memoAddBtn = function () { memoBtns.push({name:'',kitchen:'',price:'',net:''}); window.memoRenderBtnRows(); window.memoBuild(); };
  window.memoDelBtn = function (i) { memoBtns.splice(i,1); if(!memoBtns.length) memoBtns=[{name:'',kitchen:'',price:'',net:''}]; window.memoRenderBtnRows(); window.memoBuild(); };

  /* ---- section toggles ---- */
  window.memoRenderBlocks = function () {
    const box = document.getElementById('memoBlocks');
    box.innerHTML = MEMO_BLOCKS.map((b, i) => `
      <div class="mb-1" style="background:#f6f8fa;border:1px solid #e3e7ec;border-radius:7px;padding:4px 8px;">
        <div class="d-flex align-items-center gap-2 small fw-bold">
          <span class="d-flex flex-column" style="line-height:.7;">
            <button type="button" class="btn btn-link p-0 text-dark" style="font-size:.7rem;${i===0?'visibility:hidden':''}" title="เลื่อนขึ้น" onclick="window.memoMoveBlock(${i},-1)"><i class="fas fa-caret-up"></i></button>
            <button type="button" class="btn btn-link p-0 text-dark" style="font-size:.7rem;${i===MEMO_BLOCKS.length-1?'visibility:hidden':''}" title="เลื่อนลง" onclick="window.memoMoveBlock(${i},1)"><i class="fas fa-caret-down"></i></button>
          </span>
          <label class="d-flex align-items-center gap-2 m-0 flex-grow-1" style="cursor:pointer;">
            <input type="checkbox" class="form-check-input m-0" ${b.on ? 'checked' : ''} onchange="window.memoToggleBlock(${i}, this.checked)">${b.label}
          </label>
          <span class="text-muted" style="font-size:.62rem;font-weight:600;">#${i+1}</span>
        </div>
        <textarea class="form-control form-control-sm mt-1" rows="1" style="font-size:.72rem;resize:vertical;" placeholder="+ เพิ่มข้อความ/บรรทัดในกล่องนี้ (Enter = ขึ้นบรรทัดใหม่)" oninput="window.memoSetNote(${i}, this.value)">${memoEsc(b.note||'')}</textarea>
      </div>`).join('');
  };
  window.memoToggleBlock = function (i, on) { MEMO_BLOCKS[i].on = on; window.memoBuild(); };
  window.memoSetNote = function (i, val) { if (MEMO_BLOCKS[i]) { MEMO_BLOCKS[i].note = val; window.memoBuild(); } };
  // เลื่อนลำดับกล่อง (Memo จะแสดงตามลำดับนี้)
  window.memoMoveBlock = function (i, dir) {
    const j = i + dir;
    if (j < 0 || j >= MEMO_BLOCKS.length) return;
    const t = MEMO_BLOCKS[i]; MEMO_BLOCKS[i] = MEMO_BLOCKS[j]; MEMO_BLOCKS[j] = t;
    window.memoRenderBlocks(); window.memoBuild();
  };

  /* ---- build preview from the editable fields ---- */
  window.memoBuild = function () {
    const v = id => (document.getElementById(id) ? document.getElementById(id).value : '').trim();
    const on = id => { const b = MEMO_BLOCKS.find(x=>x.id===id); return b && b.on; };
    const paper = document.getElementById('memoPaper');

    const subject = v('memoSubject');
    const supersede = v('memoSupersede');
    const period = v('memoPeriod');
    const channels = v('memoChannels');
    const branches = v('memoBranches');
    const btnType = v('memoBtnType');
    const fromDept = v('memoFrom') || 'Marketing';
    const toWhom = v('memoTo') || 'หน้าร้านทุกสาขาที่มีจำหน่าย';
    const posNote = v('memoPosNote');
    const effRaw = v('memoEff');
    const items = String(v('memoDetail')).replace(/\r/g,'').split('\n').map(s=>s.replace(/^\s*\d+[\.\)]\s*/,'').trim()).filter(Boolean);
    const conds = String(v('memoCondition')).replace(/\r/g,'').split('\n').map(s=>s.replace(/^\s*\d+[\.\)]\s*/,'').trim()).filter(Boolean);
    const specials = String(v('memoSpecial')).replace(/\r/g,'').split('\n').map(s=>s.replace(/^\s*\d+[\.\)]\s*/,'').trim()).filter(Boolean);
    const btns = memoBtns.filter(b => b.name || b.kitchen || b.price || b.net);

    const anything = subject||supersede||period||channels||branches||btnType||items.length||conds.length||specials.length||btns.length;
    if (!anything) { paper.innerHTML = '<div class="text-center text-muted py-5"><i class="fas fa-pen me-1"></i> เริ่มพิมพ์ด้านซ้าย หรือกด “ดึงข้อมูลจากแคมเปญ”</div>'; return; }

    // สร้าง HTML ของแต่ละกล่องเก็บไว้ใน parts แล้วประกอบ "ตามลำดับ MEMO_BLOCKS" (ตามที่ผู้ใช้จัดเรียง)
    const parts = {};
    parts.header = `<div class="text-center" style="margin-bottom:10px;">
        <img src="${MEMO_LOGO}" alt="Potato Corner" class="mp-logo" style="height:46px;width:auto;display:block;margin:0 auto 8px;">
        <div class="mp-brand">Potato Corner Thailand</div>
        <div class="mp-title">บันทึกภายใน<small>INTERNAL MEMO</small></div>
      </div>`;
    parts.title = `<div class="mp-subject" style="border-top:1px solid #eceef0;border-bottom:1px solid #eceef0;padding:12px 0;margin-bottom:16px;">${memoEsc(subject || '(หัวข้อเรื่อง)')}</div>`;

    if (supersede) parts.supersede = `<div class="mp-supersede" style="margin-bottom:16px;">${memoEsc(supersede)}</div>`;

    {
      const rows = [
        ['ระยะเวลาโปรโมชั่น', period],
        ['ช่องทางขาย', channels],
        ['สาขาที่เข้าร่วม', branches],
        ['ประเภทปุ่มโปรโมชั่นบน POS', btnType],
      ].filter(r => r[1]);
      if (rows.length) parts.keys = `<table class="mp-keys" style="margin-bottom:16px;"><tbody>${rows.map(r=>`<tr><th>${r[0]}</th><td>${memoEsc(r[1])}</td></tr>`).join('')}</tbody></table>`;
    }

    if (items.length) parts.detail = `<div class="mp-sect">รายละเอียดโปรโมชั่น</div><ol class="mp-list" style="margin-bottom:16px;">${items.map(t=>`<li>${memoEsc(t)}</li>`).join('')}</ol>`;

    if (conds.length) parts.condition = `<div class="mp-sect">เงื่อนไข</div><ol class="mp-list" style="margin-bottom:16px;">${conds.map(t=>`<li>${memoEsc(t)}</li>`).join('')}</ol>`;

    if (specials.length) parts.special = `<div class="mp-sect mp-sect-red">เงื่อนไขพิเศษ</div><ul class="mp-special" style="margin-bottom:16px;">${specials.map(t=>`<li><i class="fas fa-bullhorn"></i><span>${memoEsc(t)}</span></li>`).join('')}</ul>`;

    if (posNote || btns.length) {
      let b = `<div class="mp-sect">ปุ่มกด POS</div>`;
      if (btns.length) {
        b += `<table class="mp-btns" style="margin-bottom:${posNote?'10px':'0'};"><thead><tr><th>ชื่อปุ่ม POS</th><th>ครัว / บิล</th><th>ราคาปกติ</th><th>ราคาหลังลด</th></tr></thead><tbody>${btns.map(x=>`<tr><td>${memoEsc(x.name||'-')}</td><td class="mp-kt">${memoEsc(x.kitchen||'-')}</td><td>${(x.price!==''&&x.price!=null)?memoEsc(x.price):'-'}</td><td>${(x.net!==''&&x.net!=null)?memoEsc(x.net):'-'}</td></tr>`).join('')}</tbody></table>`;
      }
      if (posNote) b += `<div class="mp-note">${memoEsc(posNote)}</div>`;
      parts.buttons = b;
    }

    {
      const today = new Date();
      parts.footer = `<div class="mp-foot" style="margin-top:20px;">
        <div class="r"><div class="k">หัวข้อเรื่อง</div><div class="v">${memoEsc(subject || '-')}</div></div>
        <div class="r"><div class="k">จากแผนก</div><div class="v">${memoEsc(fromDept)}</div></div>
        <div class="r"><div class="k">ลงวันที่</div><div class="v">${ddmmyyyy(today)}${effRaw?'<span style="color:#9aa2ab;margin-left:18px;">วันที่มีผล</span> '+ddmmyyyy(effRaw):''}</div></div>
        <div class="r"><div class="k">ถึง</div><div class="v">${memoEsc(toWhom)}</div></div>
      </div>`;
    }

    // MKT เพิ่มข้อความเสริมแต่ละกล่อง (note ต่อท้ายในกล่องนั้น — เพิ่มได้หลายบรรทัด)
    MEMO_BLOCKS.forEach(b => {
      var nt = (b.note || '').trim(); if (!nt) return;
      var lines = nt.split('\n').map(s => s.trim()).filter(Boolean).map(s => `<div>${memoEsc(s)}</div>`).join('');
      if (!lines) return;
      parts[b.id] = (parts[b.id] || '') + `<div class="mp-addnote" style="margin:-6px 0 16px;font-size:.9rem;color:#33405a;line-height:1.5;">${lines}</div>`;
    });

    let html = '<div class="mp-top">';
    MEMO_BLOCKS.forEach(b => { if (b.on && parts[b.id]) html += parts[b.id]; });
    html += `<div class="mp-conf" style="margin-top:18px;">© Confidential and Proprietary to Rocks PC Co., Ltd. trading as Potato Corner Thailand</div>`;
    html += '</div>';
    paper.innerHTML = html;
  };

  /* ---- status banner: cross-check linked promo in the system ---- */
  window.memoRenderStatus = function () {
    var el = document.getElementById('memoStatus'); if (!el) return;
    if (!memoLinked) {
      el.innerHTML = '<span class="text-muted"><i class="fas fa-link-slash me-1"></i>ยังไม่ผูกกับแคมเปญในระบบ — ดาวน์โหลด/พิมพ์ได้เลย · ผูกภายหลังได้เมื่อทีมกรอกโปรแจ้ง IT แล้ว</span>';
      return;
    }
    var c = memoData.find(x => x.campaign === memoLinked);
    if (!c) {
      el.innerHTML = '<i class="fas fa-link me-1 text-success"></i>ผูกกับ <b>' + memoEsc(memoLinked) + '</b> <span class="text-muted">(ไม่พบในเดือนที่เลือก — กด “เช็คสถานะโปร”)</span>';
      return;
    }
    var it = (c.itStatus || '') === 'COMPLETE' ? '<span class="badge bg-success">IT เสร็จ</span>' : '<span class="badge bg-warning text-dark">รอ IT</span>';
    var op = (c.opStatus || '') === 'CONFIRMED' ? '<span class="badge bg-success">OP ยืนยัน</span>' : ((c.opStatus || '') === 'REJECTED' ? '<span class="badge bg-danger">OP ตีกลับ</span>' : '<span class="badge bg-secondary">รอ OP</span>');
    var memo = c.memoUrl ? ' <span class="badge" style="background:#c0392b"><i class="fas fa-paperclip me-1"></i>แนบ Memo แล้ว</span>' : '';
    el.innerHTML = '<i class="fas fa-link me-1 text-success"></i>ผูกกับ <b>' + memoEsc(c.campaign) + '</b> &nbsp;' + it + ' ' + op + memo;
  };

  window.memoCheckStatus = function () {
    window.memoLoadCampaigns(function () {
      var c = memoLinked ? memoData.find(x => x.campaign === memoLinked) : null;
      if (memoLinked && !c) { Swal.fire({icon:'info', title:'ยังไม่พบโปรในระบบ', html:'“'+memoEsc(memoLinked)+'” ยังไม่ถูกกรอก/ตรวจสอบ (CONFIRMED) ในระบบ', confirmButtonColor:'#2e934a'}); return; }
      Swal.fire({icon:'success', title:'อัปเดตสถานะแล้ว', timer:1100, showConfirmButton:false});
    });
  };

  /* ---- build a self-contained HTML file of the memo ---- */
  function memoStandaloneHTML() {
    var inner = document.getElementById('memoPaper').innerHTML;
    var css = '<style>'
      + 'body{font-family:\'Kanit\',sans-serif;margin:0;padding:30px 36px;color:#1a1d20;}'
      + '.mp-top{border-top:6px solid #2e934a;padding-top:18px;}'
      + '.mp-brand{font-family:\'Montserrat\',sans-serif;font-weight:800;font-size:.82rem;letter-spacing:.16em;color:#2e934a;text-transform:uppercase;}'
      + '.mp-title{font-weight:800;font-size:1.7rem;letter-spacing:.06em;line-height:1;margin-top:6px;}'
      + '.mp-title small{display:block;font-size:.78rem;font-weight:700;letter-spacing:.34em;color:#9aa2ab;margin-top:4px;}'
      + '.mp-subject{font-weight:700;font-size:1.12rem;line-height:1.35;}'
      + '.mp-supersede{color:#c0392b;font-style:italic;font-size:.86rem;line-height:1.45;background:#fdecea;border:1px solid #f3c6c0;border-radius:8px;padding:8px 12px;}'
      + '.mp-keys{width:100%;border-collapse:collapse;font-size:.92rem;}'
      + '.mp-keys th{text-align:left;vertical-align:top;font-weight:700;color:#15623c;width:190px;padding:7px 12px 7px 0;white-space:nowrap;}'
      + '.mp-keys td{vertical-align:top;padding:7px 0;border-bottom:1px dashed #e6e9ec;}'
      + '.mp-sect{font-weight:800;font-size:1rem;color:#1a1d20;border-left:5px solid #2e934a;padding-left:10px;margin:0 0 8px;}'
      + '.mp-list{margin:0;padding-left:0;list-style:none;counter-reset:mp;}'
      + '.mp-list li{counter-increment:mp;position:relative;padding:6px 0 6px 34px;font-size:.95rem;line-height:1.5;border-bottom:1px solid #f1f3f5;}'
      + '.mp-list li::before{content:counter(mp);position:absolute;left:0;top:6px;width:23px;height:23px;background:#2e934a;color:#fff;border-radius:50%;font-size:.78rem;font-weight:700;display:flex;align-items:center;justify-content:center;}'
      + '.mp-note{font-size:.9rem;line-height:1.5;background:#f6f8f5;border-radius:8px;padding:10px 14px;}'
      + '.mp-btns{width:100%;border-collapse:collapse;font-size:.86rem;}'
      + '.mp-btns thead th{background:#1a1d20;color:#fff;font-weight:600;padding:8px 10px;text-align:center;}'
      + '.mp-btns thead th:first-child{text-align:left;}'
      + '.mp-btns thead th:nth-child(2),.mp-btns tbody td:nth-child(2){text-align:left;}'
      + '.mp-btns tbody td{border:1px solid #e3e6ea;padding:7px 10px;text-align:center;}'
      + '.mp-btns tbody td:first-child{text-align:left;font-family:monospace;font-weight:700;color:#15623c;}'
      + '.mp-foot{border:1.5px solid #1a1d20;border-radius:8px;font-size:.86rem;}'
      + '.mp-foot .r{display:flex;border-bottom:1px solid #d7dbe0;}.mp-foot .r:last-child{border-bottom:none;}'
      + '.mp-foot .k{width:150px;flex:none;font-weight:700;background:#f4f6f8;padding:7px 12px;border-right:1px solid #d7dbe0;}'
      + '.mp-foot .v{padding:7px 12px;flex:1;}'
      + '.mp-conf{font-size:.68rem;color:#9aa2ab;text-align:center;border-top:1px solid #eceef0;padding-top:8px;}'
      + '.mp-sect-red{border-left-color:#d5420c !important;color:#c0392b !important;}'
      + '.mp-special{margin:0;padding:0;list-style:none;}'
      + '.mp-special li{display:flex;align-items:flex-start;gap:8px;background:linear-gradient(90deg,#d5420c,#e8632a);color:#fff;font-weight:700;font-size:.9rem;padding:8px 13px;border-radius:9px;margin-bottom:6px;line-height:1.4;}'
      + '.mp-special li i{margin-top:3px;flex:none;}'
      + '</style>';
    var title = (document.getElementById('memoSubject').value || 'MEMO');
    return '<!doctype html><html lang="th"><head><meta charset="utf-8"><title>' + memoEsc(title) + '</title>'
      + '<link href="https://fonts.googleapis.com/css2?family=Kanit:wght@400;600;700;800&family=Montserrat:wght@800&display=swap" rel="stylesheet">'
      + css + '</head><body>' + inner + '</body></html>';
  }
  function memoSafeName(s){ return String(s||'Memo').replace(/[\\/:*?"<>|]+/g,'_').replace(/\s+/g,' ').trim().slice(0,80) || 'Memo'; }

  window.memoDownload = function () {
    var subject = (document.getElementById('memoSubject').value || '').trim();
    if (!subject) { Swal.fire({icon:'warning', title:'ยังไม่มีหัวข้อเรื่อง', text:'ใส่หัวข้อเรื่องก่อนดาวน์โหลด', confirmButtonColor:'#2e934a'}); return; }
    var blob = new Blob([memoStandaloneHTML()], { type: 'text/html;charset=utf-8' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'MEMO_' + memoSafeName(subject) + '.html';
    document.body.appendChild(a); a.click();
    setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); }, 1500);
  };

  /* ---- confirm + attach memo into the campaign's memo slot ---- */
  window.memoConfirmSend = function () {
    var subject = (document.getElementById('memoSubject').value || '').trim();
    var c = (memoLinked && memoData.find(x => x.campaign === memoLinked)) || memoData.find(x => x.campaign === subject);
    if (c) memoLinked = c.campaign;
    if (!c) {
      if (!memoData.length) { Swal.fire({icon:'info', title:'ยังส่งเข้าระบบไม่ได้', html:'ยังไม่มีโปรที่ตรวจสอบในระบบให้แนบ<br><span style="font-size:13px;color:#6b7280">ดาวน์โหลด/พิมพ์ Memo ไปก่อนได้ — กลับมากด“ยืนยันส่ง” อีกครั้งเมื่อทีมกรอกโปรแจ้ง IT แล้ว</span>', confirmButtonColor:'#2e934a'}); return; }
      Swal.fire({ title:'เลือกแคมเปญที่จะแนบ Memo', input:'select', inputOptions: memoData.reduce(function(o,x,i){ o[i]=x.campaign; return o; },{}), inputPlaceholder:'เลือกแคมเปญ', showCancelButton:true, confirmButtonColor:'#2e934a' }).then(function(r){ if (r.isConfirmed && r.value !== '') { memoLinked = memoData[+r.value].campaign; window.memoRenderStatus(); window.memoConfirmSend(); } });
      return;
    }
    var proceed = function () {
      Swal.fire({ title:'กำลังส่ง...', allowOutsideClick:false, didOpen:function(){ Swal.showLoading(); } });
      var b64 = ''; try { b64 = btoa(unescape(encodeURIComponent(memoStandaloneHTML()))); } catch(e) {}
      var fileData = { base64:b64, mimeType:'text/html', fileName:'MEMO_'+memoSafeName(c.campaign)+'.html' };
      google.script.run.withSuccessHandler(function () {
        window.memoLoadCampaigns(function(){ window.memoRenderStatus(); });
        Swal.fire({icon:'success', title:'ส่ง Memo เข้าระบบแล้ว', html:'Memo ถูกแนบเข้าช่องของแคมเปญ<br><b>'+memoEsc(c.campaign)+'</b><br><span style="font-size:13px;color:#6b7280">สาขาจะเห็นปุ่ม MEMO ในหน้า Branch View</span>', confirmButtonColor:'#2e934a'});
      }).withFailureHandler(function(e){ Swal.fire('Error', String(e), 'error'); }).processEditWithFile({ campaign:c.campaign }, fileData);
    };
    if ((c.itStatus || '') !== 'COMPLETE') {
      Swal.fire({icon:'warning', title:'IT ยังทำไม่เสร็จ', html:'แคมเปญ “'+memoEsc(c.campaign)+'” IT ยังไม่ COMPLETE (สถานะ: '+memoEsc(c.itStatus||'-')+')<br>ต้องการแนบ Memo เลยไหม?', showCancelButton:true, confirmButtonText:'แนบเลย', cancelButtonText:'ยกเลิก', confirmButtonColor:'#2e934a' }).then(function(r){ if (r.isConfirmed) proceed(); });
    } else proceed();
  };
